"""Real four-to-three loopback stale RACE callback test."""
from pathlib import Path
source=Path(__file__).resolve().parent/'test_vs_four_three_race_payload.py'
code=source.read_text()
anchor="'''\ncode = code.replace(anchor, injection + '\\n' + anchor, 1)"
assert code.count(anchor)==1
extra = 'inject(\'HOST=f.HOST+\', r\'\'\'\nold="void car_link_deliver(int p,const unsigned char*b,int n){(void)p;(void)b;(void)n;}"\nnew="static int deliveries[4], delivered_pcb[4], delivered_len[4];static unsigned char delivered_bytes[4][CAR_LINK_PACKET];\\nvoid car_link_deliver(int p,const unsigned char*b,int n){assert(active>=0&&active<4);assert(n==CAR_LINK_PACKET);deliveries[active]++;delivered_pcb[active]=p;delivered_len[active]=n;memcpy(delivered_bytes[active],b,(size_t)n);}"\nassert CLIENT.count(old)==1\nCLIENT=CLIENT.replace(old,new,1)\nCLIENT+=r"""\n#include <poll.h>\nvoid drain_callback(int i){load(i);net_race_receive();save(i);}\nint callback_count(int i){return deliveries[i];}\nvoid receive_checked(int i,int before,int expect,int pcb,int value){load(i);struct pollfd p={N.fd,POLLIN,0};assert(poll(&p,1,1000)==1&&(p.revents&POLLIN));net_race_receive();assert(deliveries[i]==before+expect);if(expect){assert(delivered_pcb[i]==pcb&&delivered_len[i]==CAR_LINK_PACKET);unsigned char expected[CAR_LINK_PACKET];memset(expected,value,sizeof expected);put32(expected+PACKET_COUNT,123);assert(!memcmp(delivered_bytes[i],expected,sizeof expected));}save(i);}\n"""\nHOST=f.HOST+\'\'\')\ninject(\'MAIN="#define DEAD\', r\'\'\'\nHOST+=r"""\nvoid send_direct(int id,unsigned race,int pcb,int value){unsigned char b[9+CAR_LINK_PACKET];head(b,RACE);put32(b+4,race);b[8]=(unsigned char)pcb;memset(b+9,value,CAR_LINK_PACKET);put32(b+9+PACKET_COUNT,123);int k=-1;for(int j=0;j<H.n;j++)if(H.p[j].id==(unsigned)id)k=j;assert(k>=0&&!H.p[k].from.gk);assert(sendto(H.fd,b,sizeof b,0,(const struct sockaddr*)&H.p[k].from.a,sizeof H.p[k].from.a)==sizeof b);}\n"""\nMAIN="#define DEAD\'\'\')\ninject(\'int host_port(void),host_count(void),host_normal(void);\', \'int host_port(void),host_count(void),host_normal(void);void send_direct(int,unsigned,int,int);void drain_callback(int),receive_checked(int,int,int,int,int);int callback_count(int);\')\ninject(\'double end=deadline(0);\', \'for(int i=0;i<4;i++)if(i!=DEAD){drain_callback(i);int before=callback_count(i);send_direct(101+i,race,3,0x51);receive_checked(i,before,0,3,0x51);}double end=deadline(0);\')\ninject(\'printf("PASS 4->3 race\', \'for(int i=0;i<4;i++)if(i!=DEAD){drain_callback(i);int before=callback_count(i);send_direct(101+i,race,3,0x52);receive_checked(i,before,0,3,0x52);int sender_pcb=(i==0?1:0);send_direct(101+i,race2,sender_pcb,0x63);receive_checked(i,before,1,sender_pcb,0x63);}puts("PASS stale race blocked at real callback; race2 delivered");printf("PASS 4->3 race\')'
assert extra.count('static int deliveries[4]') == 1
extra=extra.replace('static int deliveries[4]', '#include <assert.h>\\nstatic int deliveries[4]', 1)
assert extra.count('void send_direct(int id,unsigned race,int pcb,int value){unsigned char b[9+CAR_LINK_PACKET]') == 1
extra=extra.replace('void send_direct(int id,unsigned race,int pcb,int value){unsigned char b[9+CAR_LINK_PACKET]', '#include "car.h"\n#define PACKET_COUNT 0x34\nvoid send_direct(int id,unsigned race,int pcb,int value){unsigned char b[9+CAR_LINK_PACKET]', 1)
old='net_race_receive();assert(deliveries[i]==before+expect);'
new='unsigned char peek[9+CAR_LINK_PACKET];assert(recv(N.fd,peek,sizeof peek,MSG_PEEK)==sizeof peek);assert(peek[0]==\'W\'&&peek[1]==\'V\'&&peek[2]==1&&peek[3]==RACE&&peek[8]==pcb&&peek[9]==value);net_race_receive();assert(deliveries[i]==before+expect);'
assert extra.count(old)==1
extra=extra.replace(old,new,1)
code=code.replace(anchor,'exec('+repr(extra)+')\n'+anchor,1)
exec(compile(code,str(source),'exec'),{'__file__':str(source),'__name__':'__main__'})
